import React, { useState } from 'react';

interface PhraseGuideProps {
  onBack: () => void;
  onHome: () => void;
}

const PhraseGuide: React.FC<PhraseGuideProps> = ({ onBack, onHome }) => {
  const [searchQuery, setSearchQuery] = useState('');

  const phraseCategories = [
    {
      id: 'discount',
      title: '1️⃣ 할인/이벤트 강조',
      phrases: [
        '🔥 오늘만 특가! ~50% 할인',
        '⚡ 플래시 세일 진행중',
        '🎉 신규 고객 20% 할인',
        '💎 VIP 고객 전용 특가',
        '📅 기간 한정 특가',
        '🎁 구매 시 사은품 증정'
      ]
    },
    {
      id: 'review',
      title: '2️⃣ 후기 기반 신뢰 유도',
      phrases: [
        '⭐ 4.8점 고객 만족도',
        '💬 1000+ 후기 보기',
        '👍 베스트 리뷰어 추천',
        '🏆 연속 3년 베스트셀러',
        '💯 만족도 100% 보장',
        '👥 10만 고객이 선택한'
      ]
    },
    {
      id: 'fomo',
      title: '3️⃣ 클릭 유도형 (FOMO)',
      phrases: [
        '⏰ 마감 임박! 재고 소진',
        '🚨 마지막 기회 놓치지 마세요',
        '💥 오늘 하루만! 내일부터 가격 인상',
        '🔥 핫딜 마감 30분 전',
        '⚡ 빠른 구매가 관건!',
        '🎯 한정 수량 선착순'
      ]
    },
    {
      id: 'mypage',
      title: '4️⃣ 마이페이지 배너용',
      phrases: [
        '💝 내가 찜한 그 상품, 오늘 할인 중!',
        '🔥 1년 중 제일 핫해! ~90%',
        '😱 놓치면 후회할 베스트템',
        '📊 이번 달 인기템 TOP5',
        '🎁 나만을 위한 맞춤 추천',
        '⭐ 내 취향 저격 상품 모음'
      ]
    }
  ];

  const allPhrases = phraseCategories.flatMap(category => category.phrases);

  const filteredPhrases = searchQuery
    ? allPhrases.filter(phrase => phrase.toLowerCase().includes(searchQuery.toLowerCase()))
    : [];

  const suggestedKeywords = ['할인', '이벤트', '신상', '후기', '마감임박', '무료배송', '한정수량', '고객'];

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            📣 키워드로 문구 찾기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            어떤 문구를 찾고 계신가요?
          </h3>
          <input
            type="text"
            className="input"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="예: 할인, 신상, 무료배송"
            style={{ width: '100%', marginBottom: '15px' }}
          />

          <div style={{ marginBottom: '20px' }}>
            <span style={{ marginRight: '10px', color: '#64748b', fontSize: '0.9rem' }}>추천 키워드:</span>
            {suggestedKeywords.map(keyword => (
              <button
                key={keyword}
                className="btn-tag"
                onClick={() => setSearchQuery(keyword)}
              >
                #{keyword}
              </button>
            ))}
          </div>
        </div>

        {searchQuery && (
          <div className="mb-20">
            <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
              🔍 '{searchQuery}' 검색 결과
            </h3>

            {filteredPhrases.length > 0 ? (
              <div className="card">
                <div className="grid">
                  {filteredPhrases.map((phrase, index) => (
                    <div key={index} className="card" style={{ padding: '15px' }}>
                      <p style={{ 
                        fontSize: '1rem', 
                        color: '#1e293b', 
                        fontWeight: '500',
                        lineHeight: '1.4'
                      }}>
                        {phrase}
                      </p>
                      <button 
                        className="btn btn-secondary" 
                        style={{ 
                          marginTop: '10px', 
                          fontSize: '0.8rem',
                          padding: '6px 12px'
                        }}
                        onClick={() => navigator.clipboard.writeText(phrase)}
                      >
                        복사하기
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <p style={{ color: '#64748b' }}>검색 결과가 없습니다. 다른 키워드로 검색해보세요.</p>
            )}
          </div>
        )}

        {!searchQuery && (
          <div className="tip">
            <strong>💡 이렇게 검색해보세요!</strong><br/>
            '오늘만', '마감', '추천', '고객' 등 상품이나 이벤트와 관련된 다양한 키워드로 검색하여 딱 맞는 문구를 찾아보세요.
          </div>
        )}
      </div>
    </div>
  );
};

export default PhraseGuide;
